mkdir -p cmd/inspect-demo && cat > inspect.go <<'EOF'
// Package inspect deeply pretty-prints arbitrary Go values for debugging.
//
// It wraps github.com/davecgh/go-spew with defaults tuned for inspection:
// nested pointers are followed, unexported fields are shown, cycles are
// detected, and map keys are sorted so output is stable across runs.
package inspect

import (
	"io"
	"os"

	"github.com/davecgh/go-spew/spew"
)

// Config controls how values are rendered.
type Config = spew.ConfigState

// Default is the configuration used by the package-level helpers.
var Default = &Config{
	Indent:                  "  ",
	SortKeys:                true, // deterministic map output
	DisablePointerAddresses: true, // stable output across runs
	DisableCapacities:       true,
	ContinueOnMethod:        true, // show Stringer/error output *and* the underlying fields
	MaxDepth:                0,    // unlimited
}

// Sdump returns a deep, human-readable representation of the values.
func Sdump(values ...any) string { return Default.Sdump(values...) }

// Fdump writes a deep representation of the values to w.
func Fdump(w io.Writer, values ...any) { Default.Fdump(w, values...) }

// Dump writes a deep representation of the values to stderr, keeping
// debugging output out of a program's stdout.
func Dump(values ...any) { Default.Fdump(os.Stderr, values...) }
EOF
cat > inspect_test.go <<'EOF'
package inspect

import (
	"strings"
	"testing"
)

type node struct {
	Name     string
	children []*node
	parent   *node
	meta     map[string]int
}

func TestSdumpDeepAndCyclic(t *testing.T) {
	root := &node{Name: "root", meta: map[string]int{"b": 2, "a": 1}}
	child := &node{Name: "child", parent: root}
	root.children = append(root.children, child)

	out := Sdump(root)

	for _, want := range []string{"root", "child", "children", "already shown"} {
		if !strings.Contains(out, want) {
			t.Errorf("output missing %q:\n%s", want, out)
		}
	}
	if strings.Index(out, `"a"`) > strings.Index(out, `"b"`) {
		t.Errorf("map keys not sorted:\n%s", out)
	}
	if Sdump(root) != out {
		t.Error("output is not deterministic")
	}
}
EOF
cat > cmd/inspect-demo/main.go <<'EOF'
// Command inspect-demo shows inspect's output on a nested, cyclic structure.
package main

import (
	"errors"
	"fmt"

	"example.com/inspect"
)

type Config struct {
	Name    string
	Ports   []int
	Labels  map[string]string
	Backend *Backend
	err     error
}

type Backend struct {
	Addr   string
	Parent *Config // creates a cycle
}

func main() {
	cfg := &Config{
		Name:   "svc",
		Ports:  []int{80, 443},
		Labels: map[string]string{"tier": "web", "env": "prod"},
		err:    errors.New("boom"),
	}
	cfg.Backend = &Backend{Addr: "10.0.0.1:5432", Parent: cfg}

	fmt.Print(inspect.Sdump(cfg))
}
EOF
cat > .gitignore <<'EOF'
/inspect-demo
*.test
*.out
EOF
gofmt -l . ; go mod tidy && go vet ./... && go test ./... && go run ./cmd/inspect-demo

